$ErrorActionPreference='SilentlyContinue'
$r=Test-NetConnection -ComputerName 127.0.0.1 -Port 7890 -WarningAction SilentlyContinue
if($r.TcpTestSucceeded){Write-Output "7890 LISTENING => 代理已启动"}
else{Write-Output "7890 NOT LISTENING => 代理仍没起来"}
Write-Output "== 代理类进程 =="
Get-Process | Where-Object {$_.ProcessName -match 'clash|v2ray|sing-box|xray|verge|mihomo|nekoray|proxy|hiddify'} | Select-Object ProcessName,Id | Format-Table -AutoSize
Write-Output "== 其他常见代理端口监听情况 =="
foreach($p in 7890,7891,7897,1080,10809,2080,8888,20171){ $rr=Test-NetConnection -ComputerName 127.0.0.1 -Port $p -WarningAction SilentlyContinue; "$p : $($rr.TcpTestSucceeded)" }

$ErrorActionPreference='SilentlyContinue'
$r=Test-NetConnection -ComputerName 127.0.0.1 -Port 7890 -WarningAction SilentlyContinue
if($r.TcpTestSucceeded){
  Write-Output "7890 LISTENING => 代理已启动，测试出口"
  try { $t=Invoke-WebRequest -Uri 'https://datacenter.eastmoney.com/securities/api/data/v1/get?reportName=RPT_F10_FINANCE_MAINFINADATA&columns=SECUCODE&pageSize=1&pageNumber=1&source=HSF10&client=PC' -Proxy 'http://127.0.0.1:7890' -TimeoutSec 12 -UseBasicParsing; "proxy -> $($t.StatusCode)" } catch { "proxy egress err: $($_.Exception.Message)" }
} else {
  Write-Output "7890 NOT LISTENING => 代理仍没起来"
  Get-Process | Where-Object {$_.ProcessName -match 'clash|v2ray|sing-box|xray|verge|mihomo|nekoray|proxy|hiddify'} | Select-Object ProcessName,Id | Format-Table -AutoSize
}

Select-String -Path '分析产出\screen_sz.py' -Pattern "^def main|argparse|--base|pick_base|def run|__main__" | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
Write-Output "---- screen_sh tail ----"
Select-String -Path '分析产出\screen_sh.py' -Pattern "^def main|argparse|--base|pick_base|__main__|print\(" | Select-Object -Last 12 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
